use crate::*;
use crate::memory::{arithmetic, bytes};
use crate::types::{invalid, limit, stopped};
use std::marker::PhantomData;

/// Copy-only, allocation-free scalar records supported by the job arena.
/// Sealed: nested heap payloads cannot bypass accounting through an element.
pub trait JobElement: Copy + private::Element {}
#[derive(Debug, PartialEq, Eq)]
pub struct JobBuffer<T> { owner: u64, slot: usize, serial: u64, marker: PhantomData<T> }
impl<T> Copy for JobBuffer<T> {}
impl<T> Clone for JobBuffer<T> { fn clone(&self) -> Self { *self } }

/// Reference caps apply to retained actual capacity, including nested grid data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RasterPool { Scratch, Dash, Grid, Boundary, Output }
impl RasterPool {
    fn cap(self) -> usize { match self {
        Self::Scratch => 64 * 1024 * 1024,
        Self::Dash => 16 * 1024 * 1024,
        Self::Grid => 16 * 1024 * 1024,
        Self::Boundary => 25_000_000, // 200M bits
        Self::Output => usize::MAX,
    }}
    fn error(self) -> Diagnostic { limit(match self {
        Self::Scratch => LimitKind::Scratch, Self::Dash => LimitKind::DashCache,
        Self::Grid => LimitKind::Grid, Self::Boundary => LimitKind::Scratch,
        Self::Output => LimitKind::ReservedBytes,
    }) }
}
struct Slot {
    serial: u64,
    data: private::Storage,
    lease: AllocationLease,
    pool: RasterPool,
    cap: usize,
    active: bool,
    next_free: Option<usize>,
}
/// The sole owner of every buffer. Moving/copying a handle never transfers data.
/// Drop destroys all data and the ledger; no caller release or Drop allocation.
pub struct RasterJob {
    ledger: ChargeLedger,
    slots: Vec<Slot>,
    metadata: Option<AllocationLease>,
    free: Option<usize>,
    next: u64,
    pools: [usize; 5],
}
impl RasterJob {
    /// Move the SAME source/job ledger used by the coordinator into its owner.
    /// Existing admitted leases remain the coordinator'"'s explicit responsibility.
    pub fn new(ledger: ChargeLedger) -> Self {
        Self { ledger, slots: Vec::new(), metadata: None, free: None,
            next: 1, pools: [0; 5] }
    }
    pub fn source_owner(&self) -> &SourceOwner { self.ledger.source_owner() }
    pub fn validate_source(&self, source: &SourceOwner) -> Result<()> {
        if std::sync::Arc::ptr_eq(source, self.source_owner()) { Ok(()) }
        else { Err(invalid(0)) }
    }
    pub fn stats(&self) -> RenderMemoryStats { self.ledger.stats() }
    pub fn work(&self) -> RenderWorkStats { self.ledger.work }
    pub fn charge_work(&mut self, kind: WorkKind, units: u64) -> Result<()> {
        self.ledger.work.charge(kind, units)
    }
    fn checked<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&Slot> {
        if h.owner "'!= self.ledger.identity() { return Err(invalid(0)); }
        let s = self.slots.get(h.slot).ok_or_else(|| invalid(0))?;
        if !s.active || s.serial != h.serial || T::get(&s.data).is_none() {
            return Err(invalid(0));
        }
        Ok(s)
    }
    pub fn slice<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&[T]> {
        Ok(T::get(&self.checked(h)?.data).ok_or_else(|| invalid(0))?)
    }
    /// Mutable elements only; capacity, ownership and logical length stay private.
    pub fn slice_mut<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<&mut [T]> {
        self.checked(h)?;
        Ok(T::get_mut(&mut self.slots[h.slot].data).ok_or_else(|| invalid(0))?)
    }
    pub fn capacity<T: JobElement>(&self, h: JobBuffer<T>) -> Result<usize> {
        Ok(T::get(&self.checked(h)?.data).ok_or_else(|| invalid(0))?.capacity())
    }
    fn metadata(&mut self, control: &mut dyn WorkControl) -> Result<()> {
        if self.free.is_some() || self.slots.len() < self.slots.capacity() { return Ok(()); }
        let target = self.slots.len().checked_add(1).ok_or_else(arithmetic)?;
        let (mut replacement, lease) = self.ledger.allocate::<Slot>(
            AllocationTag::None, target, control)?;
        // All fallible work precedes the indivisible move. No cloned source/payloads.
        replacement.append(&mut self.slots);
        self.slots = replacement;
        if let Some(old) = self.metadata.replace(lease) { self.ledger.release(old)?; }
        Ok(())
    }
    /// Create a buffer with an explicit engine element cap (no smaller default).
    pub fn buffer<T: JobElement>(&mut self, pool: RasterPool, cap: usize,
        control: &mut dyn WorkControl) -> Result<JobBuffer<T>> {
        control.checkpoint().map_err(stopped)?;
        let serial = self.next;
        let next = serial.checked_add(1).ok_or_else(arithmetic)?;
        self.metadata(control)?;
        let lease = self.ledger.admit(AllocationTag::None, 0)?;
        if let Err(e) = control.checkpoint().map_err(stopped) {
            self.ledger.release(lease)?; return Err(e);
        }
        let slot = self.free.unwrap_or(self.slots.len());
        let entry = Slot { serial, data: T::wrap(Vec::new()), lease, pool, cap,
            active: true, next_free: None };
        if slot == self.slots.len() { self.slots.push(entry); }
        else { self.free = self.slots[slot].next_free; self.slots[slot] = entry; }
        self.next = next;
        Ok(JobBuffer { owner: self.ledger.identity(), slot, serial, marker: PhantomData })
    }
    /// Replacement reserves old+new overlap BEFORE allocating, then moves values.
    /// A failed/canceled reserve preserves old contents, capacity and handle.
    pub fn reserve<T: JobElement>(&mut self, h: JobBuffer<T>, capacity: usize,
        control: &mut dyn WorkControl) -> Result<()> {
        let s = self.checked(h)?;
        control.checkpoint().map_err(stopped)?;
        let old = T::get(&s.data).ok_or_else(|| invalid(0))?;
        if capacity > s.cap { return Err(s.pool.error()); }
        if capacity <= old.capacity() { return Ok(()); }
        let old_bytes = bytes(old)?;
        let request = capacity.checked_mul(std::mem::size_of::<T>()).ok_or_else(arithmetic)?;
        let pool = s.pool;
        // Local caps count retained capacity, global admission also counts overlap.
        let retained = self.pools[pool as usize].checked_sub(old_bytes)
            .and_then(|n| n.checked_add(request)).ok_or_else(arithmetic)?;
        if retained > pool.cap() { return Err(pool.error()); }
        let tag = if pool == RasterPool::Output { AllocationTag::Output }
            else { AllocationTag::ReferenceIndex };
        let (mut replacement, lease) = self.ledger.allocate::<T>(tag, capacity, control)?;
        let actual = bytes(&replacement)?;
        let retained = self.pools[pool as usize] - old_bytes;
        let Some(retained) = retained.checked_add(actual).filter(|n| *n <= pool.cap()) else {
            drop(replacement); self.ledger.release(lease)?; return Err(pool.error());
        };
        let s = &mut self.slots[h.slot];
        replacement.append(T::get_mut(&mut s.data).ok_or_else(|| invalid(0))?);
        s.data = T::wrap(replacement);
        let old_lease = std::mem::replace(&mut s.lease, lease);
        self.ledger.release(old_lease)?;
        self.pools[pool as usize] = retained;
        Ok(())
    }
    /// Copy-only append. Cancellation is checked in the actual copy loop;
    /// partial unpublished suffix is removed, successful reserve capacity retained.
    pub fn extend<T: JobElement>(&mut self, h: JobBuffer<T>, values: &[T],
        control: &mut dyn WorkControl) -> Result<()> {
        let len = self.slice(h)?.len();
        let target = len.checked_add(values.len()).ok_or_else(arithmetic)?;
        self.reserve(h, target, control)?;
        let dst = T::get_mut(&mut self.slots[h.slot].data).ok_or_else(|| invalid(0))?;
        for value in values {
            if let Err(e) = control.charge(WorkKind::SourceRead, 1).map_err(stopped) {
                dst.truncate(len); return Err(e);
            }
            dst.push(*value);
        }
        if let Err(e) = control.checkpoint().map_err(stopped) {
            dst.truncate(len); return Err(e);
        }
        Ok(())
    }
    pub fn truncate<T: JobElement>(&mut self, h: JobBuffer<T>, len: usize) -> Result<()> {
        self.checked(h)?;
        T::get_mut(&mut self.slots[h.slot].data).ok_or_else(|| invalid(0))?.truncate(len);
        Ok(())
    }
    /// Release storage but retain the same live handle for reuse.
    pub fn clear_capacity<T: JobElement>(&mut self, h: JobBuffer<T>,
        control: &mut dyn WorkControl) -> Result<()> {
        self.checked(h)?;
        control.checkpoint().map_err(stopped)?;
        // Reuse the zero-byte original lease when possible; admission cannot allocate.
        let lease = self.ledger.admit(AllocationTag::None, 0)?;
        let s = &mut self.slots[h.slot];
        let old = bytes(T::get(&s.data).ok_or_else(|| invalid(0))?)?;
        s.data = T::wrap(Vec::new());
        self.ledger.release(std::mem::replace(&mut s.lease, lease))?;
        self.pools[s.pool as usize] -= old;
        Ok(())
    }
