#define VEXEL_RASTER_SHAPE_RENDER_INTERNAL_H

#include "shape_render.h"

#include <stddef.h>
#include <stdint.h>

#define RASTER_STROKE_DASH_EPSILON 1e-12
#define RASTER_DASH_CACHE_MAX_STEPS 1000000U
#define RASTER_STROKE_GRID_MAX_CELLS 65536U
#define RASTER_STROKE_GRID_MAX_REFS 1000000U
#define RASTER_STROKE_GRID_MAX_AXIS 128U
#define RASTER_STROKE_GRID_CELL_SIZE 1.0
#define RASTER_DASH_CACHE_BYTE_LIMIT (16U * 1024U * 1024U)

typedef struct raster_stroke_grid_cell {
    size_t first;
    size_t count;
} raster_stroke_grid_cell;

typedef struct raster_dash_segment {
    geom_edge edge;
    svg_shape_linecap start_cap;
    svg_shape_linecap end_cap;
} raster_dash_segment;

typedef struct raster_dash_join {
    geom_point previous;
    geom_point vertex;
    geom_point next;
} raster_dash_join;

typedef struct raster_dash_shape_range {
    size_t segment_first;
    size_t segment_count;
    size_t join_first;
    size_t join_count;
    raster_stroke_grid_cell *grid_cells;
    uint32_t *grid_refs;
    double grid_min_x;
    double grid_min_y;
    double grid_cell_size;
    uint16_t grid_columns;
    uint16_t grid_rows;
    size_t grid_cell_count;
    size_t grid_ref_count;
} raster_dash_shape_range;

typedef struct raster_shape_dash_cache {
    raster_dash_segment *segments;
    size_t segment_count;
    size_t segment_capacity;
    raster_dash_join *joins;
    size_t join_count;
use crate::types::{invalid, limit, stopped};
use crate::*;
/// Preserved C stroke-grid encoding: high bit tags a global join index.
pub const STROKE_GRID_JOIN_BIT: u32 = 0x8000_0000;
impl DashCache {
    pub fn validate(&self, control: &mut dyn WorkControl) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if self.shapes.len() > 65536 {
            return Err(limit(LimitKind::Shapes));
        }
        for segment in &self.segments {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            if ![
                segment.edge.a.x,
                segment.edge.a.y,
                segment.edge.b.x,
                segment.edge.b.y,
            ]
            .into_iter()
            .all(f64::is_finite)
            {
                return Err(invalid(0));
            }
        }
        for join in &self.joins {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            if ![join.previous, join.vertex, join.next]
                .into_iter()
                .all(vexel_geometry::finite_point)
            {
                return Err(invalid(0));
            }
        }
        for range in &self.shapes {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            range.segments.require(self.segments.len(), 0)?;
            range.joins.require(self.joins.len(), 0)?;
            if ![range.grid_min_x, range.grid_min_y, range.grid_cell_size]
                .into_iter()
                .all(f64::is_finite)
            {
                return Err(invalid(0));
            }
            let cells = (range.grid_columns as usize)
                .checked_mul(range.grid_rows as usize)
                .ok_or_else(crate::memory::arithmetic)?;
            if cells != range.grid_cells.len()
                || ((cells == 0) != (range.grid_columns == 0 && range.grid_rows == 0))
                || (cells != 0 && range.grid_cell_size <= 0.0)
            {
                return Err(invalid(0));
            }
            for cell in &range.grid_cells {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                TableRange {
                    first: cell.first,
                    count: cell.count,
                }
                .require(range.grid_refs.len(), 0)?;
            }
            for reference in &range.grid_refs {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let index = (*reference & !STROKE_GRID_JOIN_BIT) as usize;
                let allowed = if *reference & STROKE_GRID_JOIN_BIT != 0 {
                    range.joins
                } else {
                    range.segments
                };
                if index < allowed.first
                    || index >= allowed.end().ok_or_else(crate::memory::arithmetic)?
                {
                    return Err(invalid(0));
                }
            }
        }
        Ok(())
    }
}

