/// Original shape_bounds.c cap: marking operations, NOT boundary bit count.
pub const RASTER_BOUNDARY_WORK_LIMIT: usize = 200_000_000;
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct BoundaryWork { units: usize }
impl BoundaryWork {
    pub fn units(self) -> usize { self.units }
    /// Call inside actual marking loops, with the original work amount. Native
    /// allocation/drop is not charged as marking work.
    pub fn charge(&mut self, units: usize, control: &mut dyn WorkControl) -> Result<()> {
        let total = self.units.checked_add(units).ok_or_else(crate::memory::arithmetic)?;
        if total > RASTER_BOUNDARY_WORK_LIMIT { return Err(crate::types::limit(LimitKind::Work)); }
        let amount = u64::try_from(units).map_err(|_| crate::memory::arithmetic())?;
        control.charge(WorkKind::BoundaryMark, amount).map_err(crate::types::stopped)?;
        self.units = total;
        Ok(())
    }
}
